#define main historical_main
#include "../gabor-cuda/main.cu"
#undef main
#include <vector>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{double*out;double theta,cy,cx,ct,st,scale,sx2,sy2,fx;std::vector<double>expected;std::vector<long double>gold;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;int h=97,w=131;double sx=13.0/(2.0*sqrt(2.0*log(2.0))),sy=2.65*sx;std::vector<Case>cases;for(double theta:{45.0,0.0}){Case c;c.theta=theta;c.cy=h/2.0;c.cx=w/2.0;c.ct=cos(theta);c.st=sin(theta);c.scale=1.0/(2.0*M_PI*sx*sy);c.sx2=sx*sx;c.sy2=sy*sy;c.fx=1.0/13.0;double*ref=generateGaborKernelHost(h,w,13,2.65,theta);c.expected.assign(ref,ref+h*w);free(ref);for(int y=0;y<h;y++)for(int x=0;x<w;x++){long double dx=x-c.cx,dy=y-c.cy;long double u=(long double)c.ct*dx-(long double)c.st*dy,v=(long double)c.ct*dy+(long double)c.st*dx;c.gold.push_back((long double)c.scale*expl(-.5L*(u*u/c.sx2+v*v/c.sy2))*cosl((long double)(2.0*M_PI)*(long double)c.fx*u));}CK(cudaMalloc(&c.out,h*w*sizeof(double)));gabor<<<dim3((w+15)/16,(h+15)/16),dim3(16,16)>>>(c.out,h,w,c.cy,c.cx,c.ct,c.st,c.scale,c.sx2,c.sy2,c.fx);cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,be=0;bool ok=true;std::vector<double>out;for(auto&c:cases){CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)gabor<<<dim3((w+15)/16,(h+15)/16),dim3(16,16)>>>(c.out,h,w,c.cy,c.cx,c.ct,c.st,c.scale,c.sx2,c.sy2,c.fx);CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;std::vector<double>got(h*w);CK(cudaMemcpy(got.data(),c.out,h*w*sizeof(double),cudaMemcpyDeviceToHost));for(int i=0;i<h*w;i++){double e=fabs(got[i]-c.expected[i]),b=fabsl((long double)got[i]-c.gold[i]);ma=fmax(ma,e);be=fmax(be,b);ok&=std::isfinite(got[i])&&e<=1e-16+1e-12*fabs(c.expected[i])&&b<=1e-16+1e-12*fabsl(c.gold[i]);}out.insert(out.end(),got.begin(),got.end());}double symmetry=0;int off=h*w;for(int y=1;y<h;y++)for(int x=1;x<w;x++)symmetry=fmax(symmetry,fabs(out[off+y*w+x]-out[off+(h-y)*w+w-x]));ok&=symmetry<=1e-16;allok&=ok;char file[80];sprintf(file,"gabor_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(double),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"longdouble_oracle_max_error\":%.12g,\"central_reflection_error\":%.12g,\"timing_region\":\"sum_two_full_Gabor_kernels\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,be,symmetry,repeat,file,out.size());}for(auto&c:cases)CK(cudaFree(c.out));puts(allok?"PASS":"FAIL");return allok?0:1;}
